+
+
+
+
+
+    public int getParamCacheSize() {
+        return paramCacheSize;
+    }
+
+    public void setParamCacheSize(int paramCacheSize) {
+        if (paramCacheSize > 0) this.paramCacheSize = paramCacheSize;
